#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,subprocess
DIFF=''
root=Path("WakeGuard/app")
proc=subprocess.run(["patch","-p1","--forward","--batch"],cwd=root,input=gzip.decompress(base64.b64decode(DIFF)),stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
print(proc.stdout.decode(errors="replace"))
if proc.returncode!=0: raise SystemExit(proc.returncode)
print("Applied IGNIDO Wake Android v1.8.0 ghost-alarm guard + timer-video patch")
